create or replace function private.validate_funding_payload(r jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare required text[]:=array['id','identity','edition','financialYear','programmeId','programme','budgetHead','ministry','jurisdiction','jurisdictionLabel','purpose','channel','instrument','measure','estimate','accountingBasis','share','amountRupees','periodStart','periodEnd','cutoff','publicationDate','coverageKey','aggregation','parentKey','classification','conflict','source','notes'];s jsonb;
begin
 if jsonb_typeof(r) is distinct from 'object' or not (r ?& required) or exists(select 1 from jsonb_object_keys(r) k where k<>all(required)) then return false;end if;
 if exists(select 1 from unnest(array['id','identity','edition','financialYear','programmeId','programme','budgetHead','ministry','jurisdiction','jurisdictionLabel','purpose','channel','instrument','measure','estimate','accountingBasis','share','periodStart','periodEnd','cutoff','coverageKey','aggregation','classification','notes']) k where jsonb_typeof(r->k) is distinct from 'string') or jsonb_typeof(r->'conflict') is distinct from 'boolean' or jsonb_typeof(r->'amountRupees') not in ('string','null') or jsonb_typeof(r->'publicationDate') not in ('string','null') or jsonb_typeof(r->'parentKey') not in ('string','null') then return false;end if;
 s:=r->'source';if jsonb_typeof(s) is distinct from 'object' or not (s ?& array['hash','url','locator','retrievedAt','page']) or exists(select 1 from jsonb_object_keys(s) k where k<>all(array['hash','url','locator','retrievedAt','page'])) then return false;end if;
 if exists(select 1 from unnest(array['hash','url','locator','retrievedAt']) k where jsonb_typeof(s->k) is distinct from 'string') or jsonb_typeof(s->'page') not in ('number','null') then return false;end if;
 if length(r->>'id') not between 1 and 240 or length(r->>'identity') not between 1 and 240 or length(r->>'edition') not between 1 and 120 or length(r->>'coverageKey') not between 1 and 240 or length(r->>'programmeId') not between 1 and 200 or length(r->>'programme') not between 1 and 400 or length(r->>'ministry') not between 1 and 240 or length(r->>'budgetHead')>240 or length(r->>'jurisdictionLabel')>150 or length(coalesce(r->>'parentKey',''))>240 or length(r->>'notes')>3000 or length(s->>'locator') not between 1 and 1200 then return false;end if;
 if r->>'financialYear' !~ '^20(1[6-9]|2[0-6])-20(1[7-9]|2[0-7])$' or split_part(r->>'financialYear','-',2)::integer<>split_part(r->>'financialYear','-',1)::integer+1 or (r->>'jurisdiction'<>'national' and r->>'jurisdiction' !~ '^historical:[a-z0-9_-]+$' and r->>'jurisdiction'<>all(array['35','28','12','18','10','4','22','38','7','30','24','6','2','1','20','29','32','37','31','23','27','14','17','15','13','21','34','3','8','11','33','36','16','9','5','19'])) then return false;end if;
 if r->>'purpose' not in ('infrastructure','health','education','housing','agriculture','rural','employment','social','energy','transport','environment','digital','disaster_response','disaster_mitigation','disaster_reconstruction','other') or r->>'channel' not in ('central_sector','centrally_sponsored','development_grant','capital_loan','finance_commission','disaster_grant','other') or r->>'instrument' not in ('grant','loan','direct_expenditure','unresolved') or r->>'measure' not in ('allocated','released','reported_spent') or r->>'estimate' not in ('original','revised','not_applicable') or r->>'accountingBasis' not in ('union_budget','union_release','union_booked_expenditure','recipient_utilisation') or r->>'share' not in ('union','combined','unresolved') or r->>'aggregation' not in ('leaf','context') or r->>'classification' not in ('included','excluded','mixed_unresolved','awaiting_review') then return false;end if;
 if (r->>'amountRupees' is not null and r->>'amountRupees' !~ '^-?[0-9]{1,18}\.[0-9]{2}$') or s->>'hash' !~ '^[a-f0-9]{64}$' or s->>'url' !~ '^https://' or s->>'retrievedAt' !~ '^\d{4}-\d{2}-\d{2}T' or (s->>'page' is not null and ((s->>'page')::numeric<1 or (s->>'page')::numeric<>trunc((s->>'page')::numeric))) then return false;end if;
 if (r->>'measure'='allocated' and (r->>'estimate'='not_applicable' or r->>'accountingBasis'<>'union_budget')) or (r->>'measure'='released' and (r->>'estimate'<>'not_applicable' or r->>'accountingBasis'<>'union_release')) or (r->>'measure'='reported_spent' and (r->>'estimate'<>'not_applicable' or r->>'accountingBasis' not in ('union_booked_expenditure','recipient_utilisation'))) then return false;end if;
 if exists(select 1 from unnest(array['periodStart','periodEnd','cutoff']) k where r->>k !~ '^\d{4}-\d{2}-\d{2}$') or (r->>'publicationDate' is not null and r->>'publicationDate' !~ '^\d{4}-\d{2}-\d{2}$') then return false;end if;
 perform (r->>'cutoff')::date,(r->>'periodStart')::date,(r->>'periodEnd')::date,(s->>'retrievedAt')::timestamptz;if r->>'publicationDate' is not null then perform (r->>'publicationDate')::date;end if;
 if (r->>'periodStart')::date>(r->>'periodEnd')::date or (r->>'measure'<>'allocated' and (r->>'periodEnd')::date>(r->>'cutoff')::date) then return false;end if;
 return true;
exception when others then return false;
end $$;
revoke all on function private.validate_funding_payload(jsonb) from public,anon,authenticated;
